<template><el-dialog :model-value="modelValue" :title="course?'编辑课程':'新建课程'" width="620" @close="$emit('update:modelValue',false)"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="课程名称" prop="name"><el-input v-model="form.name"/></el-form-item><div class="form-grid"><el-form-item label="课程编号"><el-input v-model="form.code"/></el-form-item><el-form-item label="适用年级"><el-input v-model="form.grade"/></el-form-item><el-form-item label="适用专业" class="full"><el-input v-model="form.major"/></el-form-item><el-form-item label="课程简介" class="full"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="备注" class="full"><el-input v-model="form.remark" type="textarea" :rows="2"/></el-form-item></div></el-form><template #footer><el-button @click="$emit('update:modelValue',false)">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存课程</el-button></template></el-dialog></template>
<script setup>import{reactive,ref,watch}from'vue';import{ElMessage}from'element-plus';import{coursesApi}from'../../api';const p=defineProps({modelValue:Boolean,course:Object}),emit=defineEmits(['update:modelValue','saved']);const formRef=ref(),saving=ref(false),form=reactive({name:'',code:'',grade:'',major:'',description:'',remark:'',status:'ACTIVE'}),rules={name:[{required:true,message:'请输入课程名称',trigger:'blur'}]};watch(()=>p.modelValue,v=>{if(v)Object.assign(form,{name:'',code:'',grade:'',major:'',description:'',remark:'',status:'ACTIVE'},p.course||{})});const save=async()=>{await formRef.value.validate();saving.value=true;try{p.course?await coursesApi.update(p.course.id,form):await coursesApi.create(form);ElMessage.success('课程已保存');emit('update:modelValue',false);emit('saved')}finally{saving.value=false}}</script>
